enum SeatStatus { AVAILABLE, HELD, BOOKED }
enum SeatType   { NORMAL, PREMIUM, RECLINER }
enum BookingStatus { CONFIRMED, CANCELLED }

record Seat(String seatId, int row, int col, SeatType type, long price) {}
record Movie(String movieId, String title, int durationMinutes) {}
record Theater(String theaterId, String name, String city) {}

class Screen {
    private final String screenId;
    private final List<Seat> layout;  // physical seat layout, shared across shows

    public Screen(String id, List<Seat> layout) {
        this.screenId = id;
        this.layout = List.copyOf(layout);
    }
    public List<Seat> getLayout() { return layout; }
    public String getScreenId() { return screenId; }
}

class Show {
    private final String showId;
    private final Movie movie;
    private final Screen screen;
    private final LocalDateTime startTime;
    private final Map<String, SeatStatus> seatStatus;
    private final ReentrantLock lock = new ReentrantLock();

    public Show(String showId, Movie movie, Screen screen, LocalDateTime startTime) {
        this.showId = showId;
        this.movie = movie;
        this.screen = screen;
        this.startTime = startTime;
        // Initialize all seats as AVAILABLE
        this.seatStatus = new HashMap<>();
        for (Seat s : screen.getLayout()) {
            seatStatus.put(s.seatId(), SeatStatus.AVAILABLE);
        }
    }

    // ── Atomic multi-seat hold ──────────
    // All-or-nothing: if any requested seat is unavailable, the entire
    // operation fails and no seats are modified.
    public boolean tryHoldSeats(Set<String> seatIds) {
        lock.lock();
        try {
            // Phase 1: validate ALL seats are AVAILABLE
            for (String id : seatIds) {
                SeatStatus status = seatStatus.get(id);
                if (status == null || status != SeatStatus.AVAILABLE) {
                    return false;  // abort — no partial changes
                }
            }
            // Phase 2: commit — transition ALL
            for (String id : seatIds) {
                seatStatus.put(id, SeatStatus.HELD);
            }
            return true;
        } finally {
            lock.unlock();
        }
    }

    // ── Confirm held seats → BOOKED ──
    public void confirmSeats(Set<String> seatIds) {
        lock.lock();
        try {
            for (String id : seatIds) {
                SeatStatus status = seatStatus.get(id);
                if (status != SeatStatus.HELD)
                    throw new IllegalStateException(
                        "Cannot confirm seat " + id + " in status " + status);
            }
            for (String id : seatIds) {
                seatStatus.put(id, SeatStatus.BOOKED);
            }
        } finally {
            lock.unlock();
        }
    }

    // ── Release held seats → AVAILABLE (on timeout or cancel) ──
    public void releaseSeats(Set<String> seatIds) {
        lock.lock();
        try {
            for (String id : seatIds) {
                SeatStatus current = seatStatus.get(id);
                if (current == SeatStatus.HELD || current == SeatStatus.BOOKED) {
                    seatStatus.put(id, SeatStatus.AVAILABLE);
                }
                // If AVAILABLE, no-op (idempotent)
            }
        } finally {
            lock.unlock();
        }
    }

    public List<Seat> getAvailableSeats() {
        lock.lock();
        try {
            return screen.getLayout().stream()
                .filter(s -> seatStatus.get(s.seatId()) == SeatStatus.AVAILABLE)
                .toList();
        } finally {
            lock.unlock();
        }
    }

    public String getShowId() { return showId; }
    public Movie getMovie() { return movie; }
    public Screen getScreen() { return screen; }
}

class Hold {
    private final String holdId;
    private final String showId;
    private final String userId;
    private final Set<String> seatIds;
    private final Instant createdAt;
    private final Duration ttl;

    public Hold(String showId, String userId, Set<String> seatIds, Duration ttl) {
        this.holdId = UUID.randomUUID().toString();
        this.showId = showId;
        this.userId = userId;
        this.seatIds = Set.copyOf(seatIds);
        this.createdAt = Instant.now();
        this.ttl = ttl;
    }

    public boolean isExpired() {
        return Instant.now().isAfter(createdAt.plus(ttl));
    }

    public String getHoldId()   { return holdId; }
    public String getShowId()   { return showId; }
    public String getUserId()   { return userId; }
    public Set<String> getSeatIds() { return seatIds; }
}

record Booking(String bookingId, String userId, String showId,
               Set<String> seatIds, long totalAmount,
               BookingStatus status, Instant createdAt) {}

class BookingService {
    private final Map<String, Show> shows = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, Hold> holds = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, Booking> bookings = new ConcurrentHashMap<>();
    private final PaymentService paymentService;
    private final ScheduledExecutorService cleanupScheduler;
    private static final Duration HOLD_TTL = Duration.ofMinutes(5);

    public BookingService(PaymentService paymentService) {
        this.paymentService = paymentService;
        this.cleanupScheduler = Executors.newSingleThreadScheduledExecutor();
        cleanupScheduler.scheduleAtFixedRate(
            this::cleanupExpiredHolds, 30, 30, TimeUnit.SECONDS);
    }

    public List<Seat> getAvailableSeats(String showId) {
        Show show = shows.get(showId);
        if (show == null) throw new ShowNotFoundException(showId);
        return show.getAvailableSeats();
    }

    // ── holdSeats ─────────────────────────
    public String holdSeats(String showId, String userId, Set<String> seatIds) {
        if (seatIds == null || seatIds.isEmpty())
            throw new IllegalArgumentException("seatIds required");

        Show show = shows.get(showId);
        if (show == null) throw new ShowNotFoundException(showId);

        // Atomic multi-seat hold — all or nothing
        if (!show.tryHoldSeats(seatIds))
            throw new SeatUnavailableException(
                "One or more seats not available");

        Hold hold = new Hold(showId, userId, seatIds, HOLD_TTL);
        holds.put(hold.getHoldId(), hold);
        return hold.getHoldId();
    }

    // ── confirmBooking ────────────────────
    public Booking confirmBooking(String holdId, String paymentToken) {
        Hold hold = holds.get(holdId);
        if (hold == null)
            throw new InvalidHoldException("Hold not found: " + holdId);

        if (hold.isExpired()) {
            // Clean up the expired hold
            Show show = shows.get(hold.getShowId());
            if (show != null) show.releaseSeats(hold.getSeatIds());
            holds.remove(holdId);
            throw new HoldExpiredException("Hold expired, please retry");
        }

        long totalAmount = computeTotal(hold);

        // Process payment
        boolean paymentOk = paymentService.processPayment(
            hold.getUserId(), totalAmount, paymentToken);
        if (!paymentOk) {
            // Don't release the seats here — user might retry with a different card.
            // Seats will auto-release on TTL expiry if not retried.
            throw new PaymentFailedException("Payment declined");
        }

        // Confirm seats — HELD → BOOKED
        Show show = shows.get(hold.getShowId());
        try {
            show.confirmSeats(hold.getSeatIds());
        } catch (IllegalStateException e) {
            // Rare: TTL expired between our isExpired check and here.
            // Refund the payment (out of scope for the LLD).
            throw new HoldExpiredException("Hold expired during confirmation");
        }

        // Create booking record
        Booking booking = new Booking(
            UUID.randomUUID().toString(),
            hold.getUserId(),
            hold.getShowId(),
            hold.getSeatIds(),
            totalAmount,
            BookingStatus.CONFIRMED,
            Instant.now());
        bookings.put(booking.bookingId(), booking);
        holds.remove(holdId);

        return booking;
    }

    // ── cancelBooking ─────────────────────
    public void cancelBooking(String bookingId) {
        Booking b = bookings.get(bookingId);
        if (b == null) throw new IllegalArgumentException("Booking not found");
        if (b.status() != BookingStatus.CONFIRMED) return;  // already cancelled

        Show show = shows.get(b.showId());
        if (show != null) show.releaseSeats(b.seatIds());

        // Replace booking with cancelled version
        bookings.put(bookingId, new Booking(
            b.bookingId(), b.userId(), b.showId(), b.seatIds(),
            b.totalAmount(), BookingStatus.CANCELLED, b.createdAt()));
    }

    // ── Background cleanup (TTL enforcement) ──
    public void cleanupExpiredHolds() {
        holds.forEach((id, hold) -> {
            if (hold.isExpired()) {
                Show show = shows.get(hold.getShowId());
                if (show != null) show.releaseSeats(hold.getSeatIds());
                holds.remove(id);
            }
        });
    }

    private long computeTotal(Hold hold) {
        Show show = shows.get(hold.getShowId());
        return show.getScreen().getLayout().stream()
            .filter(s -> hold.getSeatIds().contains(s.seatId()))
            .mapToLong(Seat::price)
            .sum();
    }

    public void shutdown() {
        cleanupScheduler.shutdown();
    }
}

interface PaymentService {
    boolean processPayment(String userId, long amount, String token);
}
